--
-- Table structure for table `computed_metrics`
--

DROP TABLE IF EXISTS `computed_metrics`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `computed_metrics` (
  `id` int NOT NULL AUTO_INCREMENT,
  `raw_data_id` int NOT NULL,
  `formula_id` int NOT NULL,
  `metric_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `metric_value` decimal(20,6) DEFAULT NULL,
  `computed_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_computed` (`raw_data_id`,`formula_id`,`metric_name`),
  KEY `idx_raw_data` (`raw_data_id`),
  KEY `idx_formula` (`formula_id`),
  KEY `idx_metric_name` (`metric_name`),
  CONSTRAINT `computed_metrics_ibfk_1` FOREIGN KEY (`raw_data_id`) REFERENCES `raw_revenue_data` (`id`) ON DELETE CASCADE,
  CONSTRAINT `computed_metrics_ibfk_2` FOREIGN KEY (`formula_id`) REFERENCES `formulas` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1622 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

