--
-- Table structure for table `raw_revenue_data`
--

DROP TABLE IF EXISTS `raw_revenue_data`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `raw_revenue_data` (
  `id` int NOT NULL AUTO_INCREMENT,
  `channel` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `slot` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `time_unit` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `total_player_impr` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `total_ad_impr` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `rpm` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gross_revenue_usd` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `net_revenue_usd` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fetched_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `fetch_date` date NOT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_record` (`channel`,`slot`,`time_unit`,`fetch_date`),
  KEY `idx_fetch_date` (`fetch_date`),
  KEY `idx_channel` (`channel`),
  KEY `idx_time_unit` (`time_unit`)
) ENGINE=InnoDB AUTO_INCREMENT=1900 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

